/* @lc app=leetcode id=2334 lang=kotlin */
class Solution { fun validSubarraySize(nums: IntArray, threshold: Int): Int = nums.size.let { n -> IntArray(n) { -1 }.let { l -> IntArray(n) { n }.let { r -> java.util.ArrayDeque<Int>().let { s -> (0 until n).forEach { i -> run { while (s.isNotEmpty() && nums[s.peek()] >= nums[i]) s.pop() }.run { if (s.isNotEmpty()) l[i] = s.peek() }.run { s.push(i) } }.also { s.clear() }.run { (n - 1 downTo 0).forEach { i -> run { while (s.isNotEmpty() && nums[s.peek()] >= nums[i]) s.pop() }.run { if (s.isNotEmpty()) r[i] = s.peek() }.run { s.push(i) } } }.run { (0 until n).firstOrNull { i -> nums[i].toLong() * (r[it] - l[it] - 1) > threshold }?.let { r[it] - l[it] - 1 } ?: -1 } } } } }